-- never be assigned, and a direct client request answers as an unknown id.

INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "care_plans", "sensitive_check", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-0000000007d1', 'ws_worry_time', 'Worry time', NULL, 'Give worrying one time and one place, instead of all day.', false, 'worksheet', 'Give worrying one time and one place, instead of all day.', NULL, 'untangle_thoughts', 'Stimulus control: worry postponement', 'sets one daily worry window and a parked list. The parked list is what the client returns to at worry time; each entry is marked still bothering / not anymore, which is a review, never a score. A daily email reminder is the only reminder — no app notification.', 'assigned', 'light', 10, $ws_ws_worry_time${"version":1,"intro":"Worrying has a way of spreading across the whole day. Giving it one time and one place doesn't make it disappear — it gives it somewhere to wait.","fields":[{"id":"time","type":"datetime","prompt":"What time each day do you want to give it?","helper":"Pick a time when you can usually stop for a bit. It doesn't have to be perfect, and you can move it later.","withDate":false,"withTime":true,"required":true},{"id":"length","type":"choice","prompt":"How long do you want?","helper":"A shorter window is easier to keep. You can always finish early.","required":true,"options":[{"value":"ten","label":"10 minutes"},{"value":"fifteen","label":"15 minutes"},{"value":"twenty","label":"20 minutes"}]},{"id":"parked","type":"row_list","prompt":"What's parked for that time?","helper":"During the day, when a worry turns up, put it here instead of carrying it round. When your worry time comes, come back and look at each one.","maxRows":12,"addLabel":"Park a worry","columns":[{"id":"worry","label":"The worry","type":"text"},{"id":"review","label":"When you came back to it","type":"choice","options":[{"value":"still","label":"Still bothering me"},{"value":"not_anymore","label":"Not anymore"}]}]},{"id":"noticed","type":"closing_reflection","prompt":"What do you notice about the ones you parked?","helper":"Optional. A word is enough."}],"closing":{"text":"A worry kept for later is a worry you're not carrying all day."}}$ws_ws_worry_time$::jsonb, NULL, 'draft', NULL, 60, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d2', 'ws_brain_dump', 'Brain-dump', NULL, 'Empty the whole swirl onto one page, then decide whether to keep it.', false, 'worksheet', 'Empty the whole swirl onto one page, then decide whether to keep it.', NULL, 'untangle_thoughts', 'Free writing: cognitive offloading', 'one long answer, typed or spoken, with keep / let it go at the end. Let-it-go deletes the saved entry at once; the content-free safety flag stays if a check-in happened.', 'open', 'light', 5, $ws_ws_brain_dump${"version":1,"intro":"Nothing here has to be tidy. Put the whole swirl down in one place, and let it be as messy as it actually is.","fields":[{"id":"dump","type":"long_text","prompt":"What's in your head right now?","helper":"One long list is fine. Nothing has to be in order. You can type this or say it out loud — whichever is easier."},{"id":"keep","type":"choice","prompt":"What would you like to do with it?","required":true,"options":[{"value":"keep","label":"Save it","description":"It goes into Past me, private unless you choose to share it."},{"value":"delete","label":"Let it go","description":"This deletes it straight away. If OKUVU already checked in about something you wrote, your therapist may still know that a check-in happened."}]}],"closing":{"text":"You got it out of your head. That's the whole job.","discardWhen":{"field":"keep","in":["delete"]}}}$ws_ws_brain_dump$::jsonb, NULL, 'draft', NULL, 70, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d3', 'ws_unhooking', 'Unhooking from a thought', NULL, 'Say a thought back to yourself as a thought, and notice if it loosens.', false, 'worksheet', 'Say a thought back to yourself as a thought, and notice if it loosens.', NULL, 'untangle_thoughts', 'Cognitive defusion', 'the thought is read back in two fixed frames — "I''m having the thought that…" and "I notice I''m having the thought that…" — in the client''s own words. Belief is 0-100 before and after; the two numbers are shown as chosen and never subtracted.', 'assigned', 'light', 10, $ws_ws_unhooking${"version":1,"intro":"A thought can feel like a fact about the world. Saying it back as a thought — in your own words — is how it starts to sound like one.","fields":[{"id":"thought","type":"short_text","prompt":"What's the thought that keeps coming?","helper":"Write it the way it arrives, exactly as harsh as it sounds. Nothing here is edited.","required":true},{"id":"belief_before","type":"scale_0_100","prompt":"How much do you believe it right now?","minLabel":"0 = not at all","maxLabel":"100 = completely"},{"id":"readback","type":"echo","prompt":"Here it is again, a little further away.","helper":"These are your own words. Nothing has been changed.","fromField":"thought","frames":["I'm having the thought that {answer}","I notice I'm having the thought that {answer}"]},{"id":"belief_after","type":"scale_0_100","prompt":"And now, having read it back?","minLabel":"0 = not at all","maxLabel":"100 = completely"},{"id":"noticed","type":"closing_reflection","prompt":"What's different, if anything, about the thought now?","helper":"Optional. Nothing has to have changed."}],"closing":{"text":"The thought didn't have to change for you to step back from it."}}$ws_ws_unhooking$::jsonb, NULL, 'draft', NULL, 80, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d4', 'ws_sos_calm', 'SOS calm', NULL, 'One tap: a long breath out, then look around the room. Nothing to type.', false, 'worksheet', 'One tap: a long breath out, then look around the room. Nothing to type.', NULL, 'calm_my_body', 'Acute distress: paced breathing then sensory grounding', 'opens the existing extended-exhale exercise (the one with the long out-breath), then the existing 5-4-3-2-1 grounding. Nothing in either exercise is changed and nothing is written by the client. Available from Home and from chat.', 'open', 'light', 3, $ws_ws_sos_calm${"version":1,"intro":"You don't have to explain anything. Let's take one long breath out first, then look around the room together.","fields":[{"id":"first_step","type":"instruction","prompt":"Start with the long breath out. It's one breath, then another — you can stop whenever you want."}],"closing":{"text":"You're here. Take your time leaving."}}$ws_ws_sos_calm$::jsonb, NULL, 'draft', NULL, 40, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d5', 'ws_sitting_with_not_knowing', 'Sitting with not knowing', NULL, 'Let one unanswered question stay open, and see how it feels afterwards.', false, 'worksheet', 'Let one unanswered question stay open, and see how it feels afterwards.', NULL, 'untangle_thoughts', 'Intolerance of uncertainty: exposure to the unresolved', 'discomfort is rated before and after one small act of leaving something unresolved. The two numbers are read as chosen; no difference is computed and nothing is graded.', 'assigned', 'light', 5, $ws_ws_sitting_with_not_knowing${"version":1,"intro":"Some things don't have an answer yet. Trying to force one can keep you awake. This is a few minutes of letting a question stay open.","fields":[{"id":"unsure","type":"short_text","prompt":"What are you unsure about?","helper":"A few words. You don't have to explain the whole situation.","required":true},{"id":"discomfort_before","type":"scale_0_10","prompt":"How uncomfortable does leaving it unknown feel?","minLabel":"0 = not at all","maxLabel":"10 = unbearable"},{"id":"small_way","type":"short_text","prompt":"One small way you'll let it stay unknown today","helper":"Something you can actually do, or actually not do. \"I'll wait until Thursday before deciding\" counts. Checking it one more time doesn't."},{"id":"discomfort_after","type":"scale_0_10","prompt":"And now, having written that?","minLabel":"0 = not at all","maxLabel":"10 = unbearable"},{"id":"noticed","type":"closing_reflection","prompt":"What do you notice?","helper":"Optional."}],"closing":{"text":"Not knowing for a while is not the same as giving up."}}$ws_ws_sitting_with_not_knowing$::jsonb, NULL, 'draft', NULL, 90, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d6', 'ws_exam_career_pressure', 'Big day planner', NULL, 'Get the practical parts of a big day out of your head and onto one page.', false, 'worksheet', 'Get the practical parts of a big day out of your head and onto one page.', NULL, 'do_what_matters', 'Pre-event planning (exam, placement, interview)', 'the date, the prep steps with their own dates, an on-the-day list, and one sentence to read at the door. Practical only: no food amounts, no drinks targets, no body content.', 'open', 'light', 10, $ws_ws_exam_career_pressure${"version":1,"intro":"Big days take up a lot of room in your head. Putting the practical parts somewhere helps you keep your head for the day itself.","fields":[{"id":"event_date","type":"datetime","prompt":"When is it?","helper":"The date is enough.","withDate":true,"withTime":false,"required":true},{"id":"prep","type":"row_list","prompt":"What needs doing before then?","helper":"One step per line, with the day you will do it. Small steps are easier to keep.","maxRows":12,"addLabel":"Add a step","columns":[{"id":"step","label":"What","type":"text"},{"id":"by_when","label":"By when","type":"datetime"}]},{"id":"on_day","type":"checklist","prompt":"On the day","helper":"Tick these as they happen. Nothing here is a rule.","options":[{"value":"eat","label":"eat something before I go"},{"value":"leave_early","label":"leave earlier than I need to"},{"value":"take","label":"take what I need with me"},{"value":"quiet_phone","label":"put my phone on silent"},{"value":"arrive","label":"get there and sit down for a minute"},{"value":"afterwards","label":"plan something kind for afterwards"}]},{"id":"remember","type":"short_text","prompt":"What do you want to remember on the day?","helper":"One sentence you'd want to read at the door.","example":"I've done the work. I just have to turn up."}],"closing":{"text":"The day will go how it goes. You'll have done what you could."}}$ws_ws_exam_career_pressure$::jsonb, NULL, 'draft', NULL, 70, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d7', 'ws_social_situation_prep', 'Social situation prep', NULL, 'Write the prediction before, and what actually happened after.', false, 'worksheet', 'Write the prediction before, and what actually happened after.', NULL, 'do_what_matters', 'Behavioural experiment for social anxiety', 'the prediction is written before the event and checked after it. "Didn''t do it" is a legitimate outcome, not a failure, and the after-question stays hidden unless one of the two done outcomes is chosen.', 'assigned', 'light', 10, $ws_ws_social_situation_prep${"version":1,"intro":"Before something social, the mind often writes the ending in advance. This is somewhere to write that ending down — and then, later, what actually happened.","fields":[{"id":"situation","type":"short_text","prompt":"What's the situation?","helper":"A few words is enough.","example":"Drinks with the team on Friday.","required":true},{"id":"prediction","type":"short_text","prompt":"What do you think will happen?","helper":"The version your mind keeps showing you, in its own words."},{"id":"worry","type":"scale_0_10","prompt":"How worried do you feel about it?","minLabel":"0 = calm","maxLabel":"10 = very worried"},{"id":"small_try","type":"short_text","prompt":"One small thing you'll try","helper":"Small is the point. Say one sentence. Stay ten minutes. Arrive and leave when you like."},{"id":"outcome","type":"choice","prompt":"If you have done it — how did it go?","helper":"Leave this until afterwards. You can come back to this worksheet.","options":[{"value":"as_feared","label":"Went as feared"},{"value":"better","label":"Better than feared"},{"value":"didnt_do","label":"Didn't do it"}]},{"id":"actually","type":"short_text","prompt":"What actually happened?","helper":"Just what happened, in plain words.","visibleWhen":{"field":"outcome","in":["as_feared","better"]}}],"closing":{"text":"A prediction written down is a prediction you can check."}}$ws_ws_social_situation_prep$::jsonb, NULL, 'draft', NULL, 80, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d8', 'ws_family_expectations', 'Pressure map', NULL, 'See where the pressure comes from, and whose expectation it really is.', false, 'worksheet', 'See where the pressure comes from, and whose expectation it really is.', NULL, 'people_boundaries', 'Expectations mapping (family, culture, self)', 'one line per area carrying expectations, with who expects what, how heavy it feels and whose expectation it mostly is. Clarifies ownership; it does not tell the client to drop anything.', 'assigned', 'light', 10, $ws_ws_family_expectations${"version":1,"intro":"A lot of pressure comes from what we think other people expect. Mapping it shows which of it is yours, and which you picked up somewhere else.","fields":[{"id":"areas","type":"row_list","prompt":"Which areas are carrying expectations?","helper":"One line for each area that applies — studies, career, money, family, marriage, friends, the future. Skip the ones that carry nothing.","maxRows":10,"addLabel":"Add an area","columns":[{"id":"area","label":"Area","type":"choice","options":[{"value":"studies","label":"Studies"},{"value":"career","label":"Career"},{"value":"money","label":"Money"},{"value":"family","label":"Family"},{"value":"marriage","label":"Marriage"},{"value":"friends","label":"Friends"},{"value":"future","label":"The future"}]},{"id":"who","label":"Who expects what?","type":"text"},{"id":"heavy","label":"How heavy does it feel?","type":"scale_0_10"},{"id":"whose","label":"Whose expectation is it mostly?","type":"choice","options":[{"value":"mine","label":"Mostly mine"},{"value":"others","label":"Mostly other people's"}]}]},{"id":"noticed","type":"closing_reflection","prompt":"What do you notice, seeing them side by side?","helper":"Optional."}],"closing":{"text":"Naming whose expectation it is doesn't settle it. It does make it easier to see."}}$ws_ws_family_expectations$::jsonb, NULL, 'draft', NULL, 40, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000007d9', 'ws_exposure_ladder', 'Exposure ladder', NULL, 'Therapist-built: graded steps, unlocked one at a time.', false, 'worksheet', 'Therapist-built: graded steps, unlocked one at a time.', NULL, 'do_what_matters', 'Graded exposure', 'THERAPIST-ONLY. Built in the portal with the client during a session; the client sees only the steps unlocked for them, rates before and after 0-100, and above 79 gets grounding plus a suggestion to pause and bring it to session. Never a Library card, never assignable, never suggested by chat.', 'therapist_only', 'demanding', 20, $ws_ws_exposure_ladder${"version":1,"intro":"Your therapist builds this ladder with you, in session. Each step is added together, and unlocked when you are both ready for it.","fields":[{"id":"about","type":"instruction","prompt":"You will see only the steps that have been unlocked for you. For each one, rate how difficult it feels before you try it, and again afterwards. If a step feels like too much on the day, it can wait."},{"id":"before_prompt","type":"scale_0_100","prompt":"Before you try this step, how difficult does it feel?","minLabel":"0 = not difficult","maxLabel":"100 = as difficult as it gets"},{"id":"after_prompt","type":"scale_0_100","prompt":"And afterwards?","minLabel":"0 = not difficult","maxLabel":"100 = as difficult as it gets"}],"closing":{"text":"Each step is yours to take when you are ready."}}$ws_ws_exposure_ladder$::jsonb, NULL, 'draft', NULL, 90, NULL, ARRAY['anxiety_worry']::TEXT[], false, CURRENT_TIMESTAMP)
